section==='pages' && in_array($r['id'],['about','privacy','terms','faq','delivery-returns'],true))): ?><form method="post" action="/admin/<?= e($section) ?>" data-confirm="Delete this record? This cannot be undone."><?= csrf_field() ?><input type="hidden" name="section" value="<?= e($section) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= e($r['id']) ?>"><button class="text-button danger">Delete</button></form><?php endif ?></div></td></tr><?php endforeach ?></tbody></table><?php if(!$records): ?><p class="empty-state">Nothing here yet.</p><?php endif ?></div>
